// Adapter only: the already pinned Rapier performs all rigid/soft contact,
// plastic flow, topology tearing, attachments and serialization. No JS solver.
use std::collections::{BTreeMap,BTreeSet};
type SoftKey=(u32,u32);
fn key(h:SoftBodyHandle)->SoftKey{h.into_raw_parts()}
#[derive(Deserialize)]#[serde(rename_all="camelCase",deny_unknown_fields)]
struct SoftConfig{positions:Vec<[f64;3]>,velocities:Vec<[f64;3]>,masses:Vec<f64>,pinned:Vec<u32>,edges:Vec<[u32;2]>,faces:Vec<[u32;3]>,cells:Vec<[u32;4]>,kind:String,radius:f64,friction:f64,restitution:f64,damping:f64,self_contacts:bool,shape_matching:bool,volume_factor:f64,cell_model:String,material:MaterialConfig,attachments:Vec<Attachment>}
#[derive(Deserialize)]#[serde(rename_all="camelCase",deny_unknown_fields)]
struct MaterialConfig{frequency:f64,bend_frequency:f64,damping_ratio:f64,young_modulus:f64,poisson_ratio:f64,plastic_yield:f64,plastic_creep:f64,plastic_max:f64,edge_plastic_yield:f64,edge_plastic_creep:f64,edge_plastic_max:f64,tear_strain:Option<f64>,tear_force:Option<f64>,tear_smoothing:f64,interior_strength:f64,max_tears:u32,min_piece:u32}
#[derive(Deserialize)]#[serde(rename_all="camelCase",deny_unknown_fields)]struct Attachment{particle:usize,body:usize}
#[derive(Deserialize,Serialize,Clone)]#[serde(rename_all="camelCase",deny_unknown_fields)]struct Breakable{joint:usize,force:f64,torque:f64}
#[derive(Deserialize)]#[serde(rename_all="camelCase",deny_unknown_fields)]struct CoupledConfig{rigid:Config,soft:Vec<SoftConfig>,breaks:Vec<Breakable>,max_particles:usize,max_elements:usize,max_pieces:usize}
#[derive(Deserialize)]#[serde(rename_all="camelCase",deny_unknown_fields)]struct SoftControl{source:usize,force:[f64;3],pins:Vec<(u32,[f64;3])>}
#[derive(Deserialize)]#[serde(rename_all="camelCase",deny_unknown_fields)]struct Cut{source:usize,blade:[[f64;3];3]}
#[derive(Deserialize)]#[serde(rename_all="camelCase",deny_unknown_fields)]struct CoupledStep{step:u64,dt:f64,controls:Vec<Control>,soft:Vec<SoftControl>,cuts:Vec<Cut>}
#[derive(Serialize,Deserialize,Clone,Default)]struct Extra{lineage:BTreeMap<SoftKey,Vec<u32>>,source:BTreeMap<SoftKey,usize>,breaks:Vec<Breakable>,broken:BTreeSet<usize>,events:Vec<CoupledEvent>,max_particles:usize,max_elements:usize,max_pieces:usize}
#[derive(Serialize,Deserialize,Clone,Default)]#[serde(rename_all="camelCase")]
struct CoupledEvent{kind:String,source:Option<usize>,handle:Option<SoftKey>,edges:Vec<[u32;2]>,cells:Vec<[u32;4]>,removed_edges:Vec<[u32;2]>,split_particles:Vec<(u32,u32)>,inserted_particles:Vec<u32>,pieces:Vec<PieceEvent>,joint:Option<usize>,force:f64,torque:f64}
#[derive(Serialize,Deserialize,Clone)]struct PieceEvent{handle:SoftKey,particles:Vec<u32>}
thread_local!{static EXTRA:RefCell<Option<Extra>>=const{RefCell::new(None)};}
fn material(c:&MaterialConfig)->Result<SoftBodyMaterial,i32>{
 let values=[c.frequency,c.bend_frequency,c.damping_ratio,c.young_modulus,c.poisson_ratio,c.plastic_yield,c.plastic_creep,c.plastic_max,c.edge_plastic_yield,c.edge_plastic_creep,c.edge_plastic_max,c.tear_smoothing,c.interior_strength];if !valid(&values)||values.iter().any(|x|*x<0.0)||c.frequency==0.0||c.bend_frequency==0.0||c.young_modulus==0.0||c.poisson_ratio>=0.5||c.tear_strain.is_some_and(|x|!x.is_finite()||x<=0.0)||c.tear_force.is_some_and(|x|!x.is_finite()||x<=0.0)||c.max_tears==0||c.min_piece==0{return fail("E_COUPLED_MATERIAL","Invalid physical material");}
 let mut m=SoftBodyMaterial::uniform(SpringCoefficients::new(c.frequency,c.damping_ratio));m.bend_softness=SpringCoefficients::new(c.bend_frequency,c.damping_ratio);m.young_modulus=c.young_modulus;m.poisson_ratio=c.poisson_ratio;m.plastic_yield=c.plastic_yield;m.plastic_creep=c.plastic_creep;m.plastic_max=c.plastic_max;m.edge_plastic_yield=c.edge_plastic_yield;m.edge_plastic_creep=c.edge_plastic_creep;m.edge_plastic_max=c.edge_plastic_max;m.tear_strain=c.tear_strain;m.tear_force=c.tear_force;m.tear_smoothing=c.tear_smoothing;m.interior_strength=c.interior_strength;m.max_tears_per_step=c.max_tears;m.min_piece=Some(c.min_piece);Ok(m)
}
fn create_coupled(c:CoupledConfig)->Result<(State,Extra),i32>{
 let mut state=create(c.rigid)?;let mut extra=Extra{breaks:c.breaks,max_particles:c.max_particles,max_elements:c.max_elements,max_pieces:c.max_pieces,..Extra::default()};if extra.max_particles==0||extra.max_elements==0||extra.max_pieces==0||c.soft.len()>extra.max_pieces{return fail("E_COUPLED_BUDGET","Invalid soft allocation plan");}
 for b in &extra.breaks{if b.joint>=state.joints.len()||!valid(&[b.force,b.torque])||b.force<=0.0||b.torque<=0.0{return fail("E_COUPLED_PARAMETER","Invalid breakable joint");}}
 let mut total=0;let mut elements=0;
 for(i,s)in c.soft.into_iter().enumerate(){let n=s.positions.len();total+=n;elements+=s.edges.len()+s.faces.len()+s.cells.len();if total>extra.max_particles||elements>extra.max_elements{return fail("E_COUPLED_BUDGET","Soft model exceeds allocation plan");}if n==0||s.velocities.len()!=n||s.masses.len()!=n||s.positions.iter().chain(&s.velocities).any(|v|!valid(v))||s.masses.iter().any(|m|!m.is_finite()||*m<=0.0)||s.pinned.iter().any(|v|*v as usize>=n)||s.edges.iter().any(|e|e.iter().any(|v|*v as usize>=n)||e[0]==e[1])||s.faces.iter().any(|e|e.iter().any(|v|*v as usize>=n)||(0..3).any(|i|(i+1..3).any(|j|e[i]==e[j])))||s.cells.iter().any(|e|e.iter().any(|v|*v as usize>=n)||(0..4).any(|i|(i+1..4).any(|j|e[i]==e[j])))||!valid(&[s.radius,s.friction,s.restitution,s.damping,s.volume_factor])||s.radius<0.0||s.friction<0.0||!(0.0..=1.0).contains(&s.restitution)||s.damping<0.0||s.volume_factor<=0.0{return fail("E_COUPLED_PARAMETER","Invalid soft model");}
  let mut builder=SoftBodyBuilder::new(s.positions.iter().copied().map(vector).collect()).masses(s.masses).pinned_particles(s.pinned).edges(s.edges.clone()).surface(s.faces).cells(s.cells).particle_radius(s.radius).surface_collider(ColliderBuilder::ball(s.radius.max(1e-10)).friction(s.friction).restitution(s.restitution)).material(material(&s.material)?).self_contacts(s.self_contacts).shape_matching(s.shape_matching).linear_damping(s.damping).can_sleep(false).volume_factor(s.volume_factor).volume_preservation(s.kind=="solid").user_data((i+1)as u128);
  if s.kind=="rope"{builder=builder.wire(s.edges);}else if s.kind!="cloth"&&s.kind!="solid"{return fail("E_COUPLED_PARAMETER","Unsupported soft topology");}
  let dihedrals=builder.surface_dihedrals();builder=builder.dihedrals(dihedrals);builder=builder.cell_model(match s.cell_model.as_str(){"volume"=>SoftBodyCellModel::Volume,"corotational"=>SoftBodyCellModel::Corotational,"neo-hookean"=>SoftBodyCellModel::NeoHookean,_=>return fail("E_COUPLED_PARAMETER","Unknown solid constitutive model")});
  let handle=state.world.insert_soft_body(builder);let soft=state.world.soft_bodies.get_mut(handle).ok_or(-4)?;for(j,v)in s.velocities.into_iter().enumerate(){soft.set_particle_velocity(j,vector(v));}for a in s.attachments{if a.particle>=n||a.body>=state.bodies.len(){return fail("E_COUPLED_PARAMETER","Invalid rigid attachment");}soft.attach_particle(a.particle,state.bodies[a.body],&state.world.bodies);}extra.lineage.insert(key(handle),(0..n as u32).collect());extra.source.insert(key(handle),i);
 }Ok((state,extra))
}
fn tear(extra:&mut Extra,event:&SoftBodyTearEvent)->Result<(),i32>{
 let k=key(event.soft_body);let source=*extra.source.get(&k).ok_or(-4)?;let mut lineage=extra.lineage.remove(&k).ok_or(-4)?;for(copy,parent)in &event.split_particles{if *parent as usize>=lineage.len(){return Err(-4);}let value=lineage[*parent as usize];if *copy as usize>=lineage.len(){lineage.resize(*copy as usize+1,u32::MAX);}lineage[*copy as usize]=value;}for p in &event.inserted_particles{if *p as usize>=lineage.len(){lineage.resize(*p as usize+1,u32::MAX);}}
 if event.pieces.is_empty(){extra.lineage.insert(k,lineage);}else{for p in &event.pieces{let ids=p.particles.iter().map(|v|lineage.get(*v as usize).copied().ok_or(-4)).collect::<Result<Vec<_>,_>>()?;extra.lineage.insert(key(p.soft_body),ids);extra.source.insert(key(p.soft_body),source);}}
 extra.events.push(CoupledEvent{kind:"tear".into(),source:Some(source),handle:Some(k),edges:event.torn_edges.clone(),cells:event.torn_cells.clone(),removed_edges:event.removed_edges.clone(),split_particles:event.split_particles.clone(),inserted_particles:event.inserted_particles.clone(),pieces:event.pieces.iter().map(|p|PieceEvent{handle:key(p.soft_body),particles:p.particles.clone()}).collect(),..CoupledEvent::default()});Ok(())
}
struct SoftCollector{tears:Mutex<Vec<SoftBodyTearEvent>>,limit:usize,overflow:Mutex<bool>}
impl EventHandler for SoftCollector{
 fn handle_collision_event(&self,_:&RigidBodySet,_:&ColliderSet,_:CollisionEvent,_:Option<&ContactPair>){}
 fn handle_contact_force_event(&self,_:f64,_:&RigidBodySet,_:&ColliderSet,_:&ContactPair,_:f64){}
 fn handle_soft_body_tear_event(&self,_:&SoftBodySet,e:&SoftBodyTearEvent){let mut events=self.tears.lock().unwrap();if events.len()>=self.limit{*self.overflow.lock().unwrap()=true;}else{events.push(e.clone());}}
}
fn coupled_step(s:&mut State,e:&mut Extra,input:CoupledStep)->Result<(),i32>{
 if input.step!=s.step+1||input.dt!=s.dt||input.controls.len()!=s.bodies.len(){return fail("E_COUPLED_TIME","Fixed step identity differs");}e.events.clear();let mut used=BTreeSet::new();for c in input.controls{if c.index>=s.bodies.len()||!used.insert(c.index)||!valid(&c.force)||!valid(&c.torque)||c.target.is_some_and(|v|!valid(&v)){return fail("E_COUPLED_PARAMETER","Invalid rigid control");}let b=&mut s.world.bodies[s.bodies[c.index]];b.reset_forces(false);b.reset_torques(false);b.add_force(vector(c.force),true);b.add_torque(vector(c.torque),true);if let Some(p)=c.target{if !b.is_kinematic(){return fail("E_COUPLED_PARAMETER","Target requires kinematic body");}b.set_next_kinematic_translation(vector(p));}}
 for control in input.soft{if !valid(&control.force)||control.pins.iter().any(|(_,p)|!valid(p)){return fail("E_COUPLED_PARAMETER","Invalid soft control");}let handles=e.source.iter().filter(|(_,source)|**source==control.source).map(|(h,_)|*h).collect::<Vec<_>>();let total_mass=handles.iter().filter_map(|h|s.world.soft_bodies.get(SoftBodyHandle::from_raw_parts(h.0,h.1))).flat_map(|b|b.particles()).filter(|p|p.inv_mass()>0.0).map(|p|p.mass()).sum::<f64>();for h in handles{let Some(b)=s.world.soft_bodies.get_mut(SoftBodyHandle::from_raw_parts(h.0,h.1))else{continue;};b.reset_forces(false);if total_mass>0.0{for i in 0..b.num_particles(){let mass=b.particles()[i].mass();if b.particles()[i].inv_mass()>0.0{b.add_particle_force(i,vector(control.force)*(mass/total_mass),true);}}}let line=e.lineage.get(&h).ok_or(-4)?;for(index,source)in line.iter().enumerate(){for(id,p)in &control.pins{if source==id{b.set_particle_kinematic_target(index,vector(*p));}}}}}
 let collector=SoftCollector{tears:Mutex::new(Vec::new()),limit:s.max_events,overflow:Mutex::new(false)};s.world.step_with_events(&(),&collector);if !s.world.quarantine().is_empty(){return fail("E_COUPLED_NUMERIC","Rapier quarantined nonfinite state");}if *collector.overflow.lock().unwrap(){return fail("E_COUPLED_BUDGET","Tear event budget exceeded");}for event in collector.tears.into_inner().unwrap(){tear(e,&event)?;}
 for cut in input.cuts{if cut.blade.iter().any(|p|!valid(p)){return fail("E_COUPLED_PARAMETER","Invalid blade");}let handles=e.source.iter().filter(|(_,source)|**source==cut.source).map(|(h,_)|*h).collect::<Vec<_>>();for h in handles{if let Some(event)=s.world.cut_soft_body(SoftBodyHandle::from_raw_parts(h.0,h.1),&cut.blade.map(vector)){tear(e,&event)?;}}}
 for b in &e.breaks{if e.broken.contains(&b.joint){continue;}let handle=s.joints[b.joint];if let Some(j)=s.world.impulse_joints.get(handle){let force=j.impulses[..3].iter().map(|v|v*v).sum::<f64>().sqrt()/s.dt;let torque=j.impulses[3..].iter().map(|v|v*v).sum::<f64>().sqrt()/s.dt;if force>b.force||torque>b.torque{s.world.impulse_joints.remove(handle,true);e.broken.insert(b.joint);e.events.push(CoupledEvent{kind:"joint-break".into(),joint:Some(b.joint),force,torque,..CoupledEvent::default()});}}}
 let pieces=s.world.soft_bodies().count();let particles=s.world.soft_bodies().map(|(_,b)|b.num_particles()).sum::<usize>();let elements=s.world.soft_bodies().map(|(_,b)|b.edges().len()+b.boundary().len()+b.cells().len()).sum::<usize>();if pieces>e.max_pieces||particles>e.max_particles||elements>e.max_elements||e.events.len()>s.max_events{return fail("E_COUPLED_BUDGET","Runtime topology/event budget exceeded; reset required");}s.step=input.step;Ok(())
}
fn coupled_output(s:&State,e:&Extra,out:&mut[u8])->Result<usize,i32>{
 let bodies=s.bodies.iter().map(|h|{let b=&s.world.bodies[*h];serde_json::json!({"position":b.translation().to_array(),"rotation":b.rotation().to_array(),"linearVelocity":b.linvel().to_array(),"angularVelocity":b.angvel().to_array(),"mass":b.mass()})}).collect::<Vec<_>>();
 let soft=s.world.soft_bodies().map(|(h,b)|{let k=key(h);serde_json::json!({"handle":k,"source":e.source.get(&k),"lineage":e.lineage.get(&k),"topologyVersion":b.topology_version(),"positions":b.particle_positions().map(|v|v.to_array()).collect::<Vec<_>>(),"velocities":b.particle_velocities().map(|v|v.to_array()).collect::<Vec<_>>(),"masses":b.particles().iter().map(|p|p.mass()).collect::<Vec<_>>(),"edges":b.edges().iter().map(|edge|serde_json::json!({"vertices":edge.vertices,"restLength":edge.rest_length,"impulse":edge.impulse(),"stress":edge.stress()})).collect::<Vec<_>>(),"faces":b.boundary(),"cells":b.cells().iter().map(|c|c.vertices).collect::<Vec<_>>(),"mass":b.mass()})}).collect::<Vec<_>>();json(&serde_json::json!({"step":s.step,"bodies":bodies,"soft":soft,"events":e.events,"brokenJoints":e.broken}),out)
}
pub fn dispose(){EXTRA.with(|e|*e.borrow_mut()=None);rigid_dispose();}
pub fn run(op:u32,input:&[u8],out:&mut[u8])->Result<usize,i32>{
 if op==21{let c:CoupledConfig=serde_json::from_slice(input).map_err(|_|-4)?;let(s,e)=create_coupled(c)?;STATE.with(|v|*v.borrow_mut()=Some(s));EXTRA.with(|v|*v.borrow_mut()=Some(e));return copy(b"{}",out);}if op==8||op==6{return rigid_run(op,input,out);}
 STATE.with(|slot|{let mut slot=slot.borrow_mut();let s=slot.as_mut().ok_or(-4)?;EXTRA.with(|extra|{let mut extra=extra.borrow_mut();let e=extra.as_mut().ok_or(-4)?;match op{
 22=>{coupled_step(s,e,serde_json::from_slice(input).map_err(|_|-4)?)?;copy(b"{}",out)},
 23=>{let data=postcard::to_stdvec(&(s,e)).map_err(|_|-4)?;copy(&data,out)},
 24=>{let(state,extra):(State,Extra)=postcard::from_bytes(input).map_err(|_|-4)?;if state.dt!=s.dt||state.bodies!=s.bodies||state.colliders!=s.colliders||state.joints!=s.joints{return fail("E_COUPLED_SNAPSHOT","Snapshot configuration differs");}*s=state;*e=extra;copy(b"{}",out)},
 25=>coupled_output(s,e,out),26=>json(&queries::meshes(s)?,out),_=>Err(-3)
 }})})
}
